const getStackTags = `-- name: GetStackTags :many
SELECT name, value
FROM stack_tags
WHERE stack_id = ?
ORDER BY name
`

type GetStackTagsRow struct {
	Name  string
	Value string
}

func (q *Queries) GetStackTags(ctx context.Context, stackID string) ([]GetStackTagsRow, error) {
	rows, err := q.db.QueryContext(ctx, getStackTags, stackID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetStackTagsRow
	for rows.Next() {
		var i GetStackTagsRow
		if err := rows.Scan(&i.Name, &i.Value); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

