const runningUpdateAt = `-- name: RunningUpdateAt :one
SELECT u.version
FROM updates AS u
WHERE u.stack_id = ?
  AND u.version > ?
  AND u.dry_run = 0 AND u.kind <> 'preview'
  AND u.status <> 'not started'
  AND u.started_at_ms <= ?
  AND (u.ended_at_ms = 0 OR u.ended_at_ms > ?)
ORDER BY u.version DESC
LIMIT 1
`

type RunningUpdateAtParams struct {
	StackID     string
	Version     int64
	StartedAtMs int64
	EndedAtMs   int64
}

func (q *Queries) RunningUpdateAt(ctx context.Context, arg RunningUpdateAtParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, runningUpdateAt,
		arg.StackID,
		arg.Version,
		arg.StartedAtMs,
		arg.EndedAtMs,
	)
	var version int64
	err := row.Scan(&version)
	return version, err
}

const runningWork = `-- name: RunningWork :one
SELECT kind, id
FROM (
    SELECT CAST('backup' AS TEXT) AS kind, id FROM backups WHERE state = 'running'
    UNION ALL
    SELECT CAST('restore' AS TEXT) AS kind, id FROM restores WHERE state IN ('checking', 'applying')
) AS running_work
ORDER BY kind, id
LIMIT 1
`

type RunningWorkRow struct {
	Kind string
	ID   string
}

// Reads one backup in the running state, or else one restore in the checking
// or applying state, in one statement. The guard of the blob deletes uses it.
// A backup comes first, and the smaller ID comes first, so the answer is the
// same for the same rows.
func (q *Queries) RunningWork(ctx context.Context) (RunningWorkRow, error) {
	row := q.db.QueryRowContext(ctx, runningWork)
	var i RunningWorkRow
	err := row.Scan(&i.Kind, &i.ID)
	return i, err
}

